method MoveZeroesToEnd(arr: seq<int>) returns (result: seq<int>)
  ensures multiset(result) == multiset(arr)
  ensures result[..IdxOf(result, 0)] == FilterNonZero(arr)
  ensures result[IdxOf(result, 0)..] == FilterZero(arr)
{
  var nz, z := Partition(arr);
  Finish(arr, nz, z);
  result := nz + z;
