// splits arr into its non-zero elements and its zeros, keeping their order
method Partition(arr: seq<int>) returns (nz: seq<int>, z: seq<int>)
  ensures nz == FilterNonZero(arr) && z == FilterZero(arr)
{
  nz := [];
  z := [];
  var i := |arr|;
  while i > 0
    invariant 0 <= i <= |arr|
    invariant nz == FilterNonZero(arr[i..])
    invariant z == FilterZero(arr[i..])
  {
    i := i - 1;
    assert arr[i..] == [arr[i]] + arr[i + 1..];
    FilterCons(arr[i], arr[i + 1..]);
    if arr[i] != 0 {
      nz := [arr[i]] + nz;
    } else {
      z := [arr[i]] + z;
    }
  }
  assert arr[0..] == arr;
}

lemma FilterCons(x: int, t: seq<int>)
  ensures FilterNonZero([x] + t) == (if x != 0 then [x] else []) + FilterNonZero(t)
  ensures FilterZero([x] + t) == (if x == 0 then [x] else []) + FilterZero(t)
{
  assert ([x] + t)[1..] == t;
}

lemma FilterProps(s: seq<int>)
  ensures multiset(FilterNonZero(s)) + multiset(FilterZero(s)) == multiset(s)
  ensures forall k :: 0 <= k < |FilterNonZero(s)| ==> FilterNonZero(s)[k] != 0
  ensures forall k :: 0 <= k < |FilterZero(s)| ==> FilterZero(s)[k] == 0
{
  if |s| > 0 {
    assert s == [s[0]] + s[1..];
    FilterCons(s[0], s[1..]);
    FilterProps(s[1..]);
  }
}

lemma Finish(arr: seq<int>, nz: seq<int>, z: seq<int>)
  requires nz == FilterNonZero(arr) && z == FilterZero(arr)
  ensures multiset(nz + z) == multiset(arr)
  ensures (nz + z)[..IdxOf(nz + z, 0)] == FilterNonZero(arr)
  ensures (nz + z)[IdxOf(nz + z, 0)..] == FilterZero(arr)
{
  FilterProps(arr);
  IdxOfConcat(nz, z);
  assert (nz + z)[..|nz|] == nz;
  assert (nz + z)[|nz|..] == z;
}

lemma IdxOfConcat(nz: seq<int>, z: seq<int>)
  requires forall k :: 0 <= k < |nz| ==> nz[k] != 0
  requires |z| > 0 ==> z[0] == 0
  ensures IdxOf(nz + z, 0) == |nz|
{
  if |nz| > 0 {
    assert (nz + z)[1..] == nz[1..] + z;
    IdxOfConcat(nz[1..], z);
  }
}

