import icontract
from typing import List


def idx_of(xs: List[int], v: int) -> int:
    # index of the first occurrence of v in xs, or len(xs) if v does not occur
    return xs.index(v) if v in xs else len(xs)


@icontract.ensure(lambda arr, result: sorted(result) == sorted(arr))
@icontract.ensure(lambda arr, result: result[:idx_of(result, 0)] == [x for x in arr if x != 0])
@icontract.ensure(lambda arr, result: result[idx_of(result, 0):] == [x for x in arr if x == 0])
def MoveZeroesToEnd(arr: List[int]) -> List[int]:
    non_zeros = []
    zeros = []
    for x in arr:
        if x != 0:
            non_zeros.append(x)
        else:
            zeros.append(x)
    return non_zeros + zeros
